7	import { renderWithProviders } from '../../test-utils/render.js';
8	import { waitFor } from '../../test-utils/async.js';
9	import { act } from 'react';
10	import { vi, describe, it, expect, beforeEach } from 'vitest';
11	import { FolderTrustDialog } from './FolderTrustDialog.js';
12	import { ExitCodes } from '@google/gemini-cli-core';
13	import * as processUtils from '../../utils/processUtils.js';
14	
15	vi.mock('../../utils/processUtils.js', () => ({
16	  relaunchApp: vi.fn(),
17	}));
18	
19	const mockedExit = vi.hoisted(() => vi.fn());
20	const mockedCwd = vi.hoisted(() => vi.fn());
21	
22	vi.mock('node:process', async () => {
23	  const actual =
24	    await vi.importActual<typeof import('node:process')>('node:process');
25	  return {
26	    ...actual,
27	    exit: mockedExit,
28	    cwd: mockedCwd,
29	  };
30	});
31	
32	describe('FolderTrustDialog', () => {
33	  beforeEach(() => {
34	    vi.clearAllMocks();
35	    vi.useRealTimers();
36	    mockedCwd.mockReturnValue('/home/user/project');
37	  });
38	
39	  it('should render the dialog with title and description', async () => {
40	    const { lastFrame, waitUntilReady, unmount } = renderWithProviders(
41	      <FolderTrustDialog onSelect={vi.fn()} />,
42	    );
43	    await waitUntilReady();
44	
45	    expect(lastFrame()).toContain('Do you trust this folder?');
46	    expect(lastFrame()).toContain(
47	      'Trusting a folder allows Gemini to execute commands it suggests.',
48	    );
49	    unmount();
50	  });
51	
52	  it('should display exit message and call process.exit and not call onSelect when escape is pressed', async () => {
53	    const onSelect = vi.fn();
54	    const { lastFrame, stdin, waitUntilReady, unmount } = renderWithProviders(
55	      <FolderTrustDialog onSelect={onSelect} isRestarting={false} />,
56	    );
57	    await waitUntilReady();
58	
59	    await act(async () => {
60	      stdin.write('\u001b[27u'); // Press kitty escape key
61	    });
62	    // Escape key has a 50ms timeout in KeypressContext, so we need to wrap waitUntilReady in act
63	    await act(async () => {
64	      await waitUntilReady();
65	    });
66	
67	    await waitFor(() => {
68	      expect(lastFrame()).toContain(
69	        'A folder trust level must be selected to continue. Exiting since escape was pressed.',
70	      );
71	    });
72	    await waitFor(() => {
73	      expect(mockedExit).toHaveBeenCalledWith(
74	        ExitCodes.FATAL_CANCELLATION_ERROR,
75	      );
76	    });
77	    expect(onSelect).not.toHaveBeenCalled();
78	    unmount();
79	  });
80	
81	  it('should display restart message when isRestarting is true', async () => {
82	    const { lastFrame, waitUntilReady, unmount } = renderWithProviders(
83	      <FolderTrustDialog onSelect={vi.fn()} isRestarting={true} />,
84	    );
85	    await waitUntilReady();
86	
87	    expect(lastFrame()).toContain('Gemini CLI is restarting');
88	    unmount();
89	  });
90	
91	  it('should call relaunchApp when isRestarting is true', async () => {
92	    vi.useFakeTimers();
93	    const relaunchApp = vi.spyOn(processUtils, 'relaunchApp');
94	    const { waitUntilReady, unmount } = renderWithProviders(
95	      <FolderTrustDialog onSelect={vi.fn()} isRestarting={true} />,
96	    );
97	    await waitUntilReady();
98	    await vi.advanceTimersByTimeAsync(250);
99	    expect(relaunchApp).toHaveBeenCalled();
100	    unmount();
101	    vi.useRealTimers();
102	  });
103	
104	  it('should not call relaunchApp if unmounted before timeout', async () => {
105	    vi.useFakeTimers();
106	    const relaunchApp = vi.spyOn(processUtils, 'relaunchApp');
107	    const { waitUntilReady, unmount } = renderWithProviders(
108	      <FolderTrustDialog onSelect={vi.fn()} isRestarting={true} />,
109	    );
110	    await waitUntilReady();
111	
112	    // Unmount immediately (before 250ms)
113	    unmount();
114	
115	    await vi.advanceTimersByTimeAsync(250);
116	    expect(relaunchApp).not.toHaveBeenCalled();
117	    vi.useRealTimers();
118	  });
119	
120	  it('should not call process.exit when "r" is pressed and isRestarting is false', async () => {
121	    const { stdin, waitUntilReady, unmount } = renderWithProviders(
122	      <FolderTrustDialog onSelect={vi.fn()} isRestarting={false} />,
123	    );
124	    await waitUntilReady();
125	
126	    await act(async () => {
127	      stdin.write('r');
128	    });
129	    await waitUntilReady();
130	
131	    await waitFor(() => {
132	      expect(mockedExit).not.toHaveBeenCalled();
133	    });
134	    unmount();
135	  });
136	
137	  describe('directory display', () => {
138	    it('should correctly display the folder name for a nested directory', async () => {
139	      mockedCwd.mockReturnValue('/home/user/project');
140	      const { lastFrame, waitUntilReady, unmount } = renderWithProviders(
141	        <FolderTrustDialog onSelect={vi.fn()} />,
142	      );
143	      await waitUntilReady();
144	      expect(lastFrame()).toContain('Trust folder (project)');
145	      unmount();
146	    });
147	
148	    it('should correctly display the parent folder name for a nested directory', async () => {
149	      mockedCwd.mockReturnValue('/home/user/project');
150	      const { lastFrame, waitUntilReady, unmount } = renderWithProviders(
151	        <FolderTrustDialog onSelect={vi.fn()} />,
152	      );
153	      await waitUntilReady();
154	      expect(lastFrame()).toContain('Trust parent folder (user)');
155	      unmount();
156	    });
157	
158	    it('should correctly display an empty parent folder name for a directory directly under root', async () => {
159	      mockedCwd.mockReturnValue('/project');
160	      const { lastFrame, waitUntilReady, unmount } = renderWithProviders(
161	        <FolderTrustDialog onSelect={vi.fn()} />,
162	      );
163	      await waitUntilReady();
164	      expect(lastFrame()).toContain('Trust parent folder ()');
165	      unmount();
166	    });
167	  });
168	});
