import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import { GEMINI_DIR } from '../utils/paths.js';

/**
 * The result of scanning a workspace's `.gemini` configuration directory.
 *
 * Every field is an array so consumers can safely iterate and display counts
 * without having to guard for `undefined`.
 */
export interface FolderDiscoveryResults {
  /** Custom command names discovered under `commands/` (without extension). */
  commands: string[];
  /** MCP server names discovered in `settings.json`. */
  mcps: string[];
  /** Hook command strings discovered in `settings.json`. */
  hooks: string[];
  /** Skill names discovered under `skills/`. */
  skills: string[];
  /** Top-level `settings.json` keys (excluding `mcpServers` and `hooks`). */
  settings: string[];
  /** Human-readable warnings about potentially risky configuration. */
  securityWarnings: string[];
  /** Errors encountered while scanning the configuration directory. */
  discoveryErrors: string[];
}

/**
 * Keys within `settings.json` that carry their own dedicated discovery
 * treatment and should therefore not be surfaced in the generic `settings`
 * list.
 */
const SETTINGS_KEYS_WITH_DEDICATED_DISPLAY = new Set(['mcpServers', 'hooks']);

/**
 * Scans a workspace's `.gemini` configuration directory and summarizes its
 * contents so users can make an informed trust decision.
 */
export class FolderTrustDiscoveryService {
  /**
   * Scan the given workspace directory for Gemini configuration.
   *
   * If the `.gemini` directory does not exist, an empty (but well-formed)
   * result is returned with no errors.
   */
  static async discover(workspaceDir: string): Promise<FolderDiscoveryResults> {
    const results: FolderDiscoveryResults = {
      commands: [],
      mcps: [],
      hooks: [],
      skills: [],
      settings: [],
      securityWarnings: [],
      discoveryErrors: [],
    };

    const geminiDir = path.join(workspaceDir, GEMINI_DIR);

    if (!(await isDirectory(geminiDir))) {
      return results;
    }

    await FolderTrustDiscoveryService.discoverCommands(geminiDir, results);
    await FolderTrustDiscoveryService.discoverSkills(geminiDir, results);
    await FolderTrustDiscoveryService.discoverSettings(geminiDir, results);

    FolderTrustDiscoveryService.buildSecurityWarnings(results);

    return results;
  }

  /**
   * Discover custom commands from `.toml` files in `{GEMINI_DIR}/commands/`.
   * Command names are the file names without their extension.
   */
  private static async discoverCommands(
    geminiDir: string,
    results: FolderDiscoveryResults,
  ): Promise<void> {
    const commandsDir = path.join(geminiDir, 'commands');
    try {
      const entries = await fs.readdir(commandsDir, { withFileTypes: true });
      for (const entry of entries) {
        if (entry.isFile() && entry.name.endsWith('.toml')) {
          results.commands.push(path.basename(entry.name, '.toml'));
        }
      }
    } catch (error) {
      if (!isNotFound(error)) {
        results.discoveryErrors.push(
          `Failed to discover commands: ${getErrorMessage(error)}`,
        );
      }
    }
  }

  /**
   * Discover skills from `{GEMINI_DIR}/skills/`. A skill is any subdirectory
   * that contains a `SKILL.md` file; the skill name is the subdirectory name.
   */
  private static async discoverSkills(
    geminiDir: string,
    results: FolderDiscoveryResults,
  ): Promise<void> {
    const skillsDir = path.join(geminiDir, 'skills');
    try {
      const entries = await fs.readdir(skillsDir, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory()) {
          continue;
        }
        const skillFile = path.join(skillsDir, entry.name, 'SKILL.md');
        if (await isFile(skillFile)) {
          results.skills.push(entry.name);
        }
      }
    } catch (error) {
      if (!isNotFound(error)) {
        results.discoveryErrors.push(
          `Failed to discover skills: ${getErrorMessage(error)}`,
        );
      }
    }
  }

  /**
   * Discover MCP servers, hooks, and top-level settings keys from
   * `{GEMINI_DIR}/settings.json`.
   */
  private static async discoverSettings(
    geminiDir: string,
    results: FolderDiscoveryResults,
  ): Promise<void> {
    const settingsPath = path.join(geminiDir, 'settings.json');

    let content: string;
    try {
      content = await fs.readFile(settingsPath, 'utf-8');
    } catch (error) {
      if (!isNotFound(error)) {
        results.discoveryErrors.push(
          `Failed to discover settings: ${getErrorMessage(error)}`,
        );
      }
      return;
    }

    let parsed: unknown;
    try {
      parsed = JSON.parse(content);
    } catch (error) {
      results.discoveryErrors.push(
        `Failed to discover settings: ${getErrorMessage(error)}`,
      );
      return;
    }

    // Non-object (or array / null) settings files carry no usable structure.
    if (!isPlainObject(parsed)) {
      return;
    }

    const settings = parsed as Record<string, unknown>;

    const mcpServers = settings['mcpServers'];
    if (isPlainObject(mcpServers)) {
      results.mcps.push(...Object.keys(mcpServers));
    }

    results.hooks.push(...extractHookCommands(settings['hooks']));

    for (const key of Object.keys(settings)) {
      if (!SETTINGS_KEYS_WITH_DEDICATED_DISPLAY.has(key)) {
        results.settings.push(key);
      }
    }
  }

  /**
   * Generate security warnings for potentially risky configuration.
   */
  private static buildSecurityWarnings(results: FolderDiscoveryResults): void {
    if (results.mcps.length > 0) {
      results.securityWarnings.push(
        `This folder configures ${results.mcps.length} MCP server(s) that can run external code on your machine.`,
      );
    }

    if (results.hooks.length > 0) {
      results.securityWarnings.push(
        `This folder configures ${results.hooks.length} hook(s) that run shell commands automatically.`,
      );
    }

    if (results.commands.length > 0) {
      results.securityWarnings.push(
        `This folder defines ${results.commands.length} custom command(s).`,
      );
    }
  }
}

/**
 * Extract the `command` string from every hook defined under the `hooks` key.
 *
 * The `hooks` value maps event names to arrays of hook definitions, where each
 * definition contains a nested `hooks` array of command configurations.
 */
function extractHookCommands(hooks: unknown): string[] {
  const commands: string[] = [];
  if (!isPlainObject(hooks)) {
    return commands;
  }

  for (const definitions of Object.values(hooks)) {
    if (!Array.isArray(definitions)) {
      continue;
    }
    for (const definition of definitions) {
      if (!isPlainObject(definition)) {
        continue;
      }
      const innerHooks = (definition as { hooks?: unknown }).hooks;
      if (!Array.isArray(innerHooks)) {
        continue;
      }
      for (const hook of innerHooks) {
        if (
          isPlainObject(hook) &&
          typeof (hook as { command?: unknown }).command === 'string'
        ) {
          commands.push((hook as { command: string }).command);
        }
      }
    }
  }

  return commands;
}

