/**
 * The result of scanning a workspace's `.gemini` configuration directory.
 *
 * Every field is an array so consumers can safely iterate and display counts
 * without having to guard for `undefined`.
 */
export interface FolderDiscoveryResults {
  /** Custom command names discovered under `commands/` (without extension). */
  commands: string[];
  /** MCP server names discovered in `settings.json`. */
  mcps: string[];
  /** Hook command strings discovered in `settings.json`. */
  hooks: string[];
