/**
 * Scans a workspace's `.gemini` configuration directory and summarizes its
 * contents so users can make an informed trust decision.
 */
export class FolderTrustDiscoveryService {
  /**
   * Scan the given workspace directory for Gemini configuration.
   *
   * If the `.gemini` directory does not exist, an empty (but well-formed)
   * result is returned with no errors.
   */
  static async discover(workspaceDir: string): Promise<FolderDiscoveryResults> {
    const results: FolderDiscoveryResults = {
      commands: [],
      mcps: [],
      hooks: [],
      skills: [],
      settings: [],
      securityWarnings: [],
      discoveryErrors: [],
    };

    const geminiDir = path.join(workspaceDir, GEMINI_DIR);

    if (!(await isDirectory(geminiDir))) {
      return results;
    }

    await FolderTrustDiscoveryService.discoverCommands(geminiDir, results);
    await FolderTrustDiscoveryService.discoverSkills(geminiDir, results);
    await FolderTrustDiscoveryService.discoverSettings(geminiDir, results);

    FolderTrustDiscoveryService.buildSecurityWarnings(results);

    return results;
  }

  /**
   * Discover custom commands from `.toml` files in `{GEMINI_DIR}/commands/`.
   * Command names are the file names without their extension.
   */
  private static async discoverCommands(
    geminiDir: string,
    results: FolderDiscoveryResults,
  ): Promise<void> {
    const commandsDir = path.join(geminiDir, 'commands');
    try {
      const entries = await fs.readdir(commandsDir, { withFileTypes: true });
      for (const entry of entries) {
        if (entry.isFile() && entry.name.endsWith('.toml')) {
          results.commands.push(path.basename(entry.name, '.toml'));
        }
      }
    } catch (error) {
      if (!isNotFound(error)) {
        results.discoveryErrors.push(
