        );
      }
    }
  }

  /**
   * Discover skills from `{GEMINI_DIR}/skills/`. A skill is any subdirectory
   * that contains a `SKILL.md` file; the skill name is the subdirectory name.
   */
  private static async discoverSkills(
    geminiDir: string,
    results: FolderDiscoveryResults,
  ): Promise<void> {
    const skillsDir = path.join(geminiDir, 'skills');
    try {
      const entries = await fs.readdir(skillsDir, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory()) {
          continue;
        }
        const skillFile = path.join(skillsDir, entry.name, 'SKILL.md');
        if (await isFile(skillFile)) {
          results.skills.push(entry.name);
        }
      }
    } catch (error) {
      if (!isNotFound(error)) {
        results.discoveryErrors.push(
          `Failed to discover skills: ${getErrorMessage(error)}`,
        );
      }
    }
  }

